const body = $input.first().json.body || {};
const eventType = body.type || 'unknown';
const job = body.job || {};
const clients = body.appData?.clients || [];
const assets = body.appData?.assets || [];
const invoices = body.appData?.invoices || [];
const estimates = body.appData?.estimates || [];
const client = clients.find(item => item.id === job.clientId) || null;
const asset = assets.find(item => item.id === job.assetId) || null;
const invoice = invoices.find(item => item.jobId === job.id) || null;
const estimate = estimates.find(item => item.jobId === job.id) || null;
const nextAction = {
  job_created: 'Registrar aviso y avisar a oficina si es urgente',
  estimate_created: 'Enviar presupuesto al cliente y programar seguimiento',
  job_status_changed: 'Registrar cambio de estado en historial externo',
  invoice_created: 'Programar seguimiento de cobro',
  invoice_collected: 'Cerrar cobro y actualizar resumen diario'
}[eventType] || 'Revisar evento manualmente';
return [{ json: { ok: true, eventType, receivedAt: new Date().toISOString(), job: { id: job.id, code: job.code, status: job.status, priority: job.priority, symptoms: job.symptoms, total: job.totals?.total || 0 }, client, asset, invoice, estimate, nextAction } }];
